        vector<int> blocks;
        int cur = 0;
        for (char c : road) {
            if (c == 'x') cur++;
            else {
                if (cur > 0) blocks.push_back(cur);
                cur = 0;
            }
        }
        if (cur > 0) blocks.push_back(cur);
        sort(blocks.rbegin(), blocks.rend());

        int fixed = 0;
