class Solution {
    public int maxPotholes(String road, int budget) {
        List<Integer> blocks = new ArrayList<>();
        int cur = 0;
        for (int i = 0; i < road.length(); i++) {
            if (road.charAt(i) == 'x') {
                cur++;
            } else {
                if (cur > 0) blocks.add(cur);
                cur = 0;
            }
        }
        if (cur > 0) blocks.add(cur);
        blocks.sort((a, b) -> Integer.compare(b, a));

        int fixed = 0;
        for (int L : blocks) {
            if (budget >= L + 1) {
                budget -= (L + 1);
                fixed += L;
            } else {
                int can = Math.max(0, budget - 1);
                fixed += Math.min(L, can);
                break;
            }
        }
        return fixed;
    }
}

var maxPotholes = function(road, budget) {
    const blocks = road.split('.').filter(Boolean).map(s => s.length).sort((a, b) => b - a);
    let fixed = 0;
    for (const L of blocks) {
        if (budget >= L + 1) {
            budget -= (L + 1);
            fixed += L;
        } else {
            const can = Math.max(0, budget - 1);
            fixed += Math.min(L, can);
            break;
        }
    }
    return fixed;
};
